package net.officefloor.hq.app.holiday;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The holidays on a sheet: days a claim's due-by, fixed when the claim is added, does not count
 *  among the business days of its terms. */
@Service
public class HolidayService {

    private final HolidayRepository holidays;
    private final ClaimRepository claims;
    private final SheetService sheets;
    private final Audit audit;

    public HolidayService(HolidayRepository holidays, ClaimRepository claims, SheetService sheets, Audit audit) {
        this.holidays = holidays;
        this.claims = claims;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's holidays, the earliest first. */
    public List<Holiday> list(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId);
    }

    /** Add a holiday to the sheet. Refused when the date is already on its list. The sheet is held
     *  locked so the same date added at the same moment is checked against itself. Every claim on the
     *  sheet that is not SETTLED or VOID and is due by the holiday or later has its due-by re-fixed:
     *  worked out again from its date, with the terms it was fixed with, over the holidays now on the
     *  sheet. */
    @Transactional
    public Holiday add(String sheetId, String user, LocalDate date) {
        sheets.lock(sheetId);
        if (holidays.existsBySheetIdAndDate(sheetId, date)) {
            throw new HolidayRefusedException("The date " + date + " is already a holiday on the sheet");
        }
        Holiday saved = holidays.saveAndFlush(new Holiday(sheetId, date));
        Set<LocalDate> days = list(sheetId).stream().map(Holiday::getDate).collect(Collectors.toSet());
        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
            if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
                    || claim.getDueBy().isBefore(date)) {
                continue;
            }
            LocalDate dueBy = businessDaysAfter(days, claim.getDate(), claim.getTerms());
            if (!dueBy.equals(claim.getDueBy())) {
                claim.refix(dueBy);
                claims.saveAndFlush(claim);
            }
        }
        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + date);
        return saved;
    }

    /** The terms-th business day after a date: counting forward from the day after it, skipping
     *  every Saturday, Sunday and holiday on the sheet now. With no terms, the date itself when it
     *  is a business day, else the next one. */
    public LocalDate businessDaysAfter(String sheetId, LocalDate date, int terms) {
        Set<LocalDate> days = list(sheetId).stream().map(Holiday::getDate).collect(Collectors.toSet());
        return businessDaysAfter(days, date, terms);
    }

    /** The terms-th business day after a date, skipping weekends and the given holidays. */
    public static LocalDate businessDaysAfter(Set<LocalDate> holidays, LocalDate date, int terms) {
        LocalDate day = date;
        if (terms <= 0) {
            while (!isBusinessDay(holidays, day)) {
                day = day.plusDays(1);
            }
            return day;
        }
        for (int counted = 0; counted < terms; ) {
            day = day.plusDays(1);
            if (isBusinessDay(holidays, day)) {
                counted++;
            }
        }
        return day;
    }

    private static boolean isBusinessDay(Set<LocalDate> holidays, LocalDate day) {
        DayOfWeek dow = day.getDayOfWeek();
        return dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY && !holidays.contains(day);
    }
}
-- A sheet's holidays: a claim's due-by, fixed when it is added, is moved past any holiday on the
-- sheet then. A date is on a sheet's list at most once.
CREATE TABLE holiday (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    holiday_date DATE NOT NULL
);
CREATE UNIQUE INDEX holiday_sheet_date ON holiday (sheet_id, holiday_date);
-- A steward's flag on a person: a reason and the date it is in force until, inclusive; null while
-- the person was never flagged.
ALTER TABLE person ADD COLUMN flag_reason VARCHAR(200);
ALTER TABLE person ADD COLUMN flag_until DATE;
package net.officefloor.hq.app.sheet;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Set;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.util.AntPathMatcher;
import org.springframework.web.servlet.HandlerInterceptor;

/**
 * On an archived sheet everything stays visible and every change is refused (409) before it
 * reaches its controller, so it writes nothing to the store or the audit. Loading the sheet changes
 * nothing and is let through; so is archiving, which refuses a sheet archived already, and the bulk
 * actions, which refuse every selected item (see the bulk services).
 */
@Component
public class ArchivedGuard implements HandlerInterceptor {

    /** The sheet-scoped requests the guard watches. */
    public static final String PATTERN = "/api/sheets/{sheetId}/**";

    private static final Set<String> LET_THROUGH = Set.of(
            "/api/sheets/{sheetId}/load",
            "/api/sheets/{sheetId}/archive",
            "/api/sheets/{sheetId}/claims/open",
            "/api/sheets/{sheetId}/claims/settle",
            "/api/sheets/{sheetId}/claims/reassign",
            "/api/sheets/{sheetId}/people/grade",
            "/api/sheets/{sheetId}/people/retire");

    private final AntPathMatcher paths = new AntPathMatcher();
    private final SheetService sheets;

    public ArchivedGuard(SheetService sheets) {
        this.sheets = sheets;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String method = request.getMethod();
        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
            return true;
        }
        String path = request.getRequestURI().substring(request.getContextPath().length());
        if (!paths.match(PATTERN, path) || LET_THROUGH.stream().anyMatch(p -> paths.match(p, path))) {
            return true;
        }
        String sheetId = URLDecoder.decode(paths.extractUriTemplateVariables(PATTERN, path).get("sheetId"),
                StandardCharsets.UTF_8).trim();
        if (sheets.isArchived(sheetId)) {
            response.setStatus(HttpStatus.CONFLICT.value());
            return false;
        }
        return true;
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Set;
import net.officefloor.hq.app.AsOf;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.util.AntPathMatcher;
import org.springframework.web.servlet.HandlerInterceptor;

/**
 * While a user's screen is set to an as-of date it shows the sheet as it stood then, and every change
 * it asks for (a statement as of a date included) is refused (409) before it reaches its controller,
 * so it writes nothing to the store or the audit. Loading the sheet changes nothing and is let through.
 */
@Component
public class AsOfGuard implements HandlerInterceptor {

    /** The sheet-scoped requests the guard watches. */
    public static final String PATTERN = "/api/sheets/{sheetId}/**";

    private static final Set<String> LET_THROUGH = Set.of("/api/sheets/{sheetId}/load");

    private final AntPathMatcher paths = new AntPathMatcher();

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String method = request.getMethod();
        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
            return true;
        }
        String path = request.getRequestURI().substring(request.getContextPath().length());
        if (!paths.match(PATTERN, path) || LET_THROUGH.stream().anyMatch(p -> paths.match(p, path))) {
            return true;
        }
        String header = request.getHeader(AsOf.HEADER);
        if (header != null && !header.isBlank()) {
            response.setStatus(HttpStatus.CONFLICT.value());
            return false;
        }
        return true;
    }
}
package net.officefloor.hq.app.setting;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.util.AntPathMatcher;
import org.springframework.web.servlet.HandlerInterceptor;

/**
 * A viewer sees every screen and figure and can change nothing: every request that would change a
 * sheet is refused (403) before it reaches its controller, so it writes nothing to the store or the
 * audit. Loading a sheet changes nothing and is let through; so are the bulk actions, which a
 * viewer takes with nothing done (every selected item refused, see the bulk services), and the
 * plans' generate, which makes nothing for a viewer (see the plan service).
 */
@Component
public class ViewerGuard implements HandlerInterceptor {

    /** The sheet-scoped requests the guard watches. */
    public static final String PATTERN = "/api/sheets/{sheetId}/**";

    /** The requests a viewer may make: loading a sheet, the bulk actions that refuse every item, and
